if not isinstance(BankAccount, type):
    raise AssertionError('Step 1: BankAccount should be a class')

# Test instantiation with default balance
try:
    test1 = BankAccount('Test')
    if not hasattr(test1, '_balance') or test1._balance != 0:
        raise AssertionError('Step 1: balance should default to 0')
except Exception as e:
    raise AssertionError(f'Step 1: Error creating BankAccount: {e}')

# Test instantiation with explicit balance
test2 = BankAccount('Test', 100)
if not hasattr(test2, '_owner') or not hasattr(test2, '_balance'):
    raise AssertionError('Step 1: Should have _owner and _balance protected attributes')

print('TEST_PASSED')

BankAccount = globals().get('BankAccount')
if not BankAccount:
    raise AssertionError('Step 1: BankAccount class not defined')

# Check methods exist
required_methods = ['get_balance', 'get_owner', 'deposit', 'withdraw']
for method in required_methods:
    if not hasattr(BankAccount, method):
        raise AssertionError(f'Step 2-5: {method} method not defined')

# Test getters
account = BankAccount('Test', 500)
if account.get_balance() != 500:
    raise AssertionError('Step 2: get_balance should return the current balance')
if account.get_owner() != 'Test':
    raise AssertionError('Step 3: get_owner should return the owner name')

# Test deposit - valid
result = account.deposit(100)
if result != True:
    raise AssertionError('Step 4: deposit should return True on success')
if account.get_balance() != 600:
    raise AssertionError('Step 4: deposit should increase balance')

# Test deposit - invalid
result = account.deposit(-50)
if result != False:
    raise AssertionError('Step 4: deposit should return False for invalid amount')
if account.get_balance() != 600:
    raise AssertionError('Step 4: invalid deposit should not change balance')

# Test withdraw - valid
result = account.withdraw(200)
if result != True:
    raise AssertionError('Step 5: withdraw should return True on success')
if account.get_balance() != 400:
    raise AssertionError('Step 5: withdraw should decrease balance')

# Test withdraw - insufficient funds
result = account.withdraw(1000)
if result != False:
    raise AssertionError('Step 5: withdraw should return False for insufficient funds')
if account.get_balance() != 400:
    raise AssertionError('Step 5: failed withdraw should not change balance')

# Test withdraw - invalid amount
result = account.withdraw(-50)
if result != False:
    raise AssertionError('Step 5: withdraw should return False for negative amount')

print('TEST_PASSED')

